/**
 * World Clock (Tool Pack 28): the curated city directory.
 *
 * The directory is a hand-written SELECTION of cities. These tests check its shape, its bounds and its identity rules, that every zone is
 * one the runtime accepts, and that every (zone, country) pair agrees with a pinned copy of the IANA zone.tab
 * (tests/fixtures/zone-country.json, generated by tests/fixtures/zone-country.py). They need no Python and no tzdata install.
 */
import { test, describe } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import {
  DIRECTORY, COUNTRY_NAMES, REGIONS, MAX_ALIASES, regionOf, normalizeText, slugOf, getEntry, searchDirectory, browseRegion, placeName, countryName,
} from "../../assets/js/tools/world-clock/city-directory.js";
import { isValidZone } from "../../assets/js/tools/time-zone-converter/time-zone-engine.js";

const PROJECT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");
const snapshot = JSON.parse(fs.readFileSync(path.join(PROJECT, "tests", "fixtures", "zone-country.json"), "utf8"));

/* a zone the runtime accepts but the pinned zone.tab does not list (a newer or renamed zone). Empty today; an entry here needs a reason. */
const SNAPSHOT_EXCEPTIONS = {};

describe("the pinned zone.tab snapshot", () => {
  test("it names its release and holds zones with country codes and the list of valid codes", () => {
    assert.match(snapshot.tzdata, /^\d{4}[a-z]$/);
    assert.match(snapshot.source, /zone\.tab/);
    assert.ok(Object.keys(snapshot.zones).length > 350);
    assert.ok(snapshot.countries.length > 240 && snapshot.countries.includes("IN") && snapshot.countries.includes("GB"));
    for (const [zone, codes] of Object.entries(snapshot.zones)) {
      assert.ok(codes.length >= 1 && codes.every((c) => /^[A-Z]{2}$/.test(c) && snapshot.countries.includes(c)), zone);
    }
    assert.deepEqual(snapshot.zones["Asia/Kolkata"], ["IN"]);
  });
});

describe("shape and bounds", () => {
  test("between 150 and 250 entries, as a frozen array of frozen entries", () => {
    assert.ok(DIRECTORY.length >= 150 && DIRECTORY.length <= 250, `${DIRECTORY.length} entries`);
    assert.ok(Object.isFrozen(DIRECTORY));
    for (const e of DIRECTORY) assert.ok(Object.isFrozen(e) && Object.isFrozen(e.aliases), e.id);
  });

  test("every id is the city's slug plus the lower-case country code, valid and unique", () => {
    const seen = new Set();
    for (const e of DIRECTORY) {
      assert.match(e.id, /^[a-z0-9]+(-[a-z0-9]+)*-[a-z]{2}$/, e.id);
      assert.ok(e.id.length <= 40, e.id);
      assert.equal(e.id, `${slugOf(e.city)}-${e.country.toLowerCase()}`);
      assert.ok(!seen.has(e.id), `duplicate id ${e.id}`);
      seen.add(e.id);
    }
  });

  test("one entry per normalised city and country", () => {
    const seen = new Set();
    for (const e of DIRECTORY) {
      const key = `${normalizeText(e.city)}|${e.country}`;
      assert.ok(!seen.has(key), `duplicate city ${key}`);
      seen.add(key);
    }
  });

  test("countries have names and are real ISO codes; regions are from the allowed set and follow the zone's area", () => {
    for (const e of DIRECTORY) {
      assert.ok(COUNTRY_NAMES[e.country], `${e.id}: no country name`);
      assert.ok(snapshot.countries.includes(e.country), `${e.id}: ${e.country} is not an ISO 3166-1 code`);
      assert.ok(REGIONS.includes(e.region), e.id);
      assert.equal(e.region, regionOf(e.zone), e.id);
    }
    for (const code of Object.keys(COUNTRY_NAMES)) assert.ok(DIRECTORY.some((e) => e.country === code), `${code} is named but has no city`);
    assert.deepEqual(REGIONS, ["Africa", "Americas", "Asia", "Europe", "Oceania"]);
  });

  test("0 to 3 aliases, none equal to another entry's city, none empty, none repeated inside an entry", () => {
    const cities = new Map();
    for (const e of DIRECTORY) cities.set(normalizeText(e.city), (cities.get(normalizeText(e.city)) ?? 0) + 1);
    for (const e of DIRECTORY) {
      assert.ok(e.aliases.length <= MAX_ALIASES, e.id);
      const own = new Set([normalizeText(e.city)]);
      for (const a of e.aliases) {
        const n = normalizeText(a);
        assert.ok(n !== "", `${e.id}: empty alias`);
        assert.ok(!own.has(n), `${e.id}: alias "${a}" repeats a name`);
        own.add(n);
        assert.ok(!cities.has(n), `${e.id}: alias "${a}" is another entry's city name`);
      }
    }
  });
});

describe("zones and countries are real", () => {
  test("every zone is accepted by this runtime", () => {
    for (const e of DIRECTORY) assert.ok(isValidZone(e.zone), `${e.id}: ${e.zone} is not accepted by this runtime`);
  });

  test("every zone is in the pinned zone.tab with the entry's country (or is a reasoned, listed exception)", () => {
    for (const e of DIRECTORY) {
      const countries = snapshot.zones[e.zone];
      if (!countries) {
        assert.ok(SNAPSHOT_EXCEPTIONS[e.zone], `${e.id}: ${e.zone} is not in the pinned zone.tab (tzdata ${snapshot.tzdata}) and has no listed exception`);
        continue;
      }
      assert.ok(countries.includes(e.country), `${e.id}: zone.tab lists ${e.zone} for ${countries.join(",")}, not ${e.country}`);
    }
    for (const [zone, reason] of Object.entries(SNAPSHOT_EXCEPTIONS)) assert.ok(typeof reason === "string" && reason.length > 10, zone);
  });
});

describe("coverage promises", () => {
  const byId = (id) => getEntry(id);

  test("every unusual-offset and date-line city the specification names is present", () => {
    const need = {
      "kathmandu-np": "Asia/Kathmandu", "adelaide-au": "Australia/Adelaide", "darwin-au": "Australia/Darwin", "st-john-s-ca": "America/St_Johns",
      "tehran-ir": "Asia/Tehran", "kabul-af": "Asia/Kabul", "yangon-mm": "Asia/Yangon", "chatham-islands-nz": "Pacific/Chatham",
      "lord-howe-island-au": "Australia/Lord_Howe", "kiritimati-ki": "Pacific/Kiritimati", "pago-pago-as": "Pacific/Pago_Pago",
    };
    for (const [id, zone] of Object.entries(need)) assert.equal(byId(id)?.zone, zone, id);
  });

  test("the 22 everyday names TP19's zone search could not find each return a result here", () => {
    const names = ["Mumbai", "Delhi", "New Delhi", "Bangalore", "Chennai", "Hyderabad", "Pune", "Beijing", "San Francisco", "Washington", "Houston", "Dallas",
      "Miami", "Boston", "Seattle", "Atlanta", "Doha", "Abu Dhabi", "Tel Aviv", "Lahore", "Hanoi", "Osaka"];
    assert.equal(names.length, 22);
    for (const name of names) assert.ok(searchDirectory(name).length > 0, name);
  });

  test("India's main metros, the capitals of the largest countries and a city on every inhabited continent are present", () => {
    for (const id of ["mumbai-in", "delhi-in", "bengaluru-in", "chennai-in", "kolkata-in", "hyderabad-in", "pune-in", "ahmedabad-in", "london-gb", "paris-fr", "berlin-de",
      "washington-d-c-us", "beijing-cn", "tokyo-jp", "moscow-ru", "brasilia-br", "canberra-au", "ottawa-ca", "cairo-eg", "nairobi-ke", "johannesburg-za", "buenos-aires-ar"]) {
      assert.ok(byId(id), id);
    }
    for (const region of REGIONS) assert.ok(DIRECTORY.filter((e) => e.region === region).length >= 10, region);
  });

  test("Paraguay's Asuncion is listed: it doubles as the visible face of the tz-database version divergence case", () => {
    assert.equal(byId("asuncion-py").zone, "America/Asuncion");
  });
});

describe("names, collisions and search", () => {
  test("placeName always carries the country, so two same-named cities are told apart", () => {
    assert.equal(placeName(getEntry("london-gb")), "London, United Kingdom");
    assert.equal(placeName(getEntry("london-ca")), "London, Canada");
    assert.equal(countryName("ZZ"), "ZZ");
  });

  test("the same-name pairs in the directory are real collisions and every pair is distinguishable by id and country", () => {
    const groups = new Map();
    for (const e of DIRECTORY) groups.set(normalizeText(e.city), [...(groups.get(normalizeText(e.city)) ?? []), e]);
    const pairs = [...groups.values()].filter((g) => g.length > 1);
    assert.ok(pairs.length >= 4, "London, Birmingham, Hyderabad and San Jose are the expected collisions");
    for (const g of pairs) {
      assert.equal(new Set(g.map((e) => e.id)).size, g.length);
      assert.equal(new Set(g.map((e) => e.country)).size, g.length);
    }
    for (const name of ["London", "Birmingham", "Hyderabad"]) assert.equal(searchDirectory(name).length, 2, name);
    assert.equal(searchDirectory("san jose").length, 2);
  });

  test("normalisation drops accents and punctuation; matching ignores case and spacing", () => {
    assert.equal(normalizeText("  São Paulo!! "), "sao paulo");
    assert.equal(normalizeText("St. John's"), "st john s");
    assert.equal(slugOf("Nuku'alofa"), "nuku-alofa");
    assert.deepEqual(searchDirectory("SAO   PAULO").map((e) => e.id), ["sao-paulo-br"]);
    assert.deepEqual(searchDirectory("st johns").map((e) => e.id), ["st-john-s-ca"]);
    assert.deepEqual(searchDirectory("nukualofa"), []);
  });

  test("ranking: exact beats prefix beats word-start beats country beats contained", () => {
    assert.equal(searchDirectory("delhi")[0].id, "delhi-in");
    // "rom": Rome starts with it (rank 1); Romanian cities only match through the country name (rank 3), so they come after
    const rom = searchDirectory("rom").map((e) => e.id);
    assert.equal(rom[0], "rome-it");
    assert.ok(rom.indexOf("bucharest-ro") > rom.indexOf("rome-it"));
    // an alias that is exactly the query outranks a city that merely starts with it
    assert.equal(searchDirectory("la")[0].id, "los-angeles-us");
  });

  test("a typed zone path finds the cities that keep that clock, the city that names the zone first; a plain name does not drag in its zone-mates", () => {
    assert.deepEqual(searchDirectory("America/Chicago").map((e) => e.id), ["chicago-us", "birmingham-us", "dallas-us", "houston-us"]);
    assert.deepEqual(searchDirectory("Asia/Tokyo").map((e) => e.id), ["tokyo-jp", "osaka-jp"]);
    assert.equal(searchDirectory("Asia/Calcutta")[0].id, "kolkata-in", "the old spelling reaches the city through its alias");
    assert.equal(searchDirectory("Asia/Kolkata")[0].id, "kolkata-in");
    assert.deepEqual(searchDirectory("london").map((e) => e.id), ["london-gb", "london-ca"]); // not Birmingham or Edinburgh, which share Europe/London
    assert.deepEqual(searchDirectory("chicago").map((e) => e.id), ["chicago-us"]);
    assert.deepEqual(searchDirectory("america chicago").map((e) => e.id), [], "words with no slash are not read as a zone");
  });

  test("results are capped and deterministic, and never depend on the browser's locale", () => {
    const a = searchDirectory("a", { limit: 5 }).map((e) => e.id);
    const b = searchDirectory("a", { limit: 5 }).map((e) => e.id);
    assert.deepEqual(a, b);
    assert.equal(a.length, 5);
    assert.deepEqual(searchDirectory("", {}), []);
  });

  test("browseRegion is alphabetical and reports its uncapped total", () => {
    const { entries, total } = browseRegion("Europe", { limit: 5 });
    assert.equal(entries.length, 5);
    assert.equal(total, DIRECTORY.filter((e) => e.region === "Europe").length);
    const names = entries.map((e) => normalizeText(e.city));
    assert.deepEqual(names, [...names].sort());
  });
});
